<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Support · Atlas</title><link rel="stylesheet" href="<?=esc(url_for('assets/app.css'))?>"></head><body class="standalone-with-nav"><?=standaloneSidebar($navGroups,'support',$admin,$org,$user,$location)?><main class="page-wrap standalone-workspace"><nav class="breadcrumbs"><a href="<?=esc(url_for())?>">Atlas</a><span>›</span><strong>Support</strong></nav><header class="page-header"><div><p class="eyebrow">HELP AND ESCALATION</p><h1>Atlas support</h1><p>Record questions, defects, access problems, data concerns, or security reports.</p></div></header><?php if($notice):?><div class="page-flash success"><span>✓</span><?=esc($notice['message'])?></div><?php endif;?><section class="planning-grid"><article class="panel"><h2>New request</h2><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="create_support_request"><label>Category<select name="category"><option value="question">Question</option><option value="defect">Defect</option><option value="access">Access</option><option value="data">Data</option><option value="security">Security</option></select></label><label>Subject<input name="subject" required></label><label>Description<textarea name="description" rows="7" required></textarea></label><button class="button primary">Submit request</button></form></article><article class="panel"><h2>Organization requests</h2><?php foreach($supportRequests as $request):if(!$admin&&(int)$request['membership_id']!==(int)$org['membership_id'])continue;?><div class="planning-row"><span><strong><?=esc($request['subject'])?></strong><small><?=esc($request['category'].' · '.$request['status'].' · '.$request['created_at'])?></small></span></div><?php endforeach;?></article></section></main></body></html>
